import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabel',
  context: {
    owner: 'acme',
    repo: 'widgets',
    staleDate: '2026-07-01',
    allIssues: [],
    issuesToLabel: [],
    currentIndex: 0,
    completedCount: 0,
    skippedCount: 0,
    errorCount: 0,
  },
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'title', 'updated_at', 'labels'],
      }), { id: 'fetchIssues' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('fetchIssues'),
          target: 'processingResults',
          actions: assign({
            allIssues: ({ event }) => {
              // Handle the response - it could be structured or text
              const result = event.result;
              if (typeof result === 'string') {
                try {
                  return JSON.parse(result).issues || [];
                } catch {
                  return [];
                }
              }
              return result.issues || result || [];
            },
          }),
        },
        TOOL_ERROR: {
          guard: whenCall('fetchIssues'),
          target: 'failed',
        },
      },
    },
    processingResults: {
      entry: assign({
        issuesToLabel: ({ context }) => {
          const staleDate = new Date(context.staleDate);
          return context.allIssues
            .filter((issue) => {
              const updatedAt = new Date(issue.updated_at);
              return updatedAt < staleDate;
            })
            .map((issue) => ({
              number: issue.number,
              title: issue.title,
              existingLabels: issue.labels || [],
            }));
        },
      }),
      always: {
        target: 'labelingLoop',
      },
    },
    labelingLoop: {
      always: [
        {
          guard: ({ context }) => context.currentIndex >= context.issuesToLabel.length,
          target: 'done',
        },
        {
          target: 'labelingIssue',
        },
      ],
    },
    labelingIssue: {
      entry: toolCall('github.issue_write', ({ context }) => {
        const issue = context.issuesToLabel[context.currentIndex];
        const existingLabelNames = issue.existingLabels.map((l) => 
          typeof l === 'string' ? l : l.name
        );
        const allLabels = Array.from(new Set([...existingLabelNames, 'stale']));

        return {
          method: 'update',
          owner: context.owner,
          repo: context.repo,
          issue_number: issue.number,
          labels: allLabels,
        };
      }, { id: 'labelIssue' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('labelIssue'),
          target: 'labelingLoop',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1,
            completedCount: ({ context }) => context.completedCount + 1,
          }),
        },
        TOOL_DENIED: {
          guard: whenCall('labelIssue'),
          target: 'labelingLoop',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1,
            skippedCount: ({ context }) => context.skippedCount + 1,
          }),
        },
        TOOL_ERROR: {
          guard: whenCall('labelIssue'),
          target: 'labelingLoop',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1,
            errorCount: ({ context }) => context.errorCount + 1,
          }),
        },
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    message: `Processed ${context.issuesToLabel.length} issues: ${context.completedCount} labeled, ${context.skippedCount} skipped, ${context.errorCount} errors`,
    summary: {
      totalStaleIssues: context.issuesToLabel.length,
      completed: context.completedCount,
      skipped: context.skippedCount,
      errors: context.errorCount,
    },
  }),
});

import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabel',
  context: {
    owner: 'acme',
    repo: 'widgets',
    staleDate: '2026-07-01T00:00:00Z',
    issuesToProcess: [
      { number: 64, existingLabels: ['documentation', 'needs-triage'] },
      { number: 60, existingLabels: ['enhancement'] },
      { number: 58, existingLabels: ['bug'] },
      { number: 55, existingLabels: [] },
      { number: 51, existingLabels: [] },
      { number: 49, existingLabels: [] },
      { number: 47, existingLabels: ['enhancement'] },
      { number: 45, existingLabels: [] },
      { number: 43, existingLabels: ['bug'] },
      { number: 39, existingLabels: ['enhancement'] },
      { number: 34, existingLabels: [] },
      { number: 32, existingLabels: [] },
    ],
    currentBatch: [],
    completedCount: 0,
    failedCount: 0,
    batchIndex: 0,
  },
  initial: 'preparingBatches',
  states: {
    preparingBatches: {
      entry: assign({
        currentBatch: ({ context }) => {
          // Process in batches of 3 (3 approvals per round is safer)
          const batchSize = 3;
          const batch = context.issuesToProcess.slice(
            context.batchIndex * batchSize,
            (context.batchIndex + 1) * batchSize
          );
          return batch;
        },
      }),
      always: [
        {
          guard: ({ context }) => context.currentBatch.length === 0,
          target: 'done',
        },
        {
          target: 'labelingBatch',
        },
      ],
    },
    labelingBatch: {
      initial: 'processingFirstInBatch',
      states: {
        processingFirstInBatch: {
          always: [
            {
              guard: ({ context }) => context.currentBatch.length === 0,
              target: '#addStaleLabel.nextBatch',
            },
            {
              target: 'labelingIssue1',
            },
          ],
        },
        labelingIssue1: {
          entry: toolCall('github.issue_write', ({ context }) => {
            const issue = context.currentBatch[0];
            const allLabels = Array.from(new Set([...issue.existingLabels, 'stale']));
            return {
              method: 'update',
              owner: context.owner,
              repo: context.repo,
              issue_number: issue.number,
              labels: allLabels,
            };
          }, { id: 'issue1' }),
          on: {
            TOOL_RESULT: {
              guard: whenCall('issue1'),
              target: 'removingFirstFromBatch',
              actions: assign({
                completedCount: ({ context }) => context.completedCount + 1,
              }),
            },
            TOOL_DENIED: {
              guard: whenCall('issue1'),
              target: 'removingFirstFromBatch',
              actions: assign({
                failedCount: ({ context }) => context.failedCount + 1,
              }),
            },
            TOOL_ERROR: {
              guard: whenCall('issue1'),
              target: 'removingFirstFromBatch',
              actions: assign({
                failedCount: ({ context }) => context.failedCount + 1,
              }),
            },
          },
        },
        removingFirstFromBatch: {
          entry: assign({
            currentBatch: ({ context }) => context.currentBatch.slice(1),
          }),
          always: 'processingFirstInBatch',
        },
      },
    },
    nextBatch: {
      entry: assign({
        batchIndex: ({ context }) => context.batchIndex + 1,
      }),
      always: 'preparingBatches',
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    message: `Labeled ${context.completedCount} stale issues, ${context.failedCount} failed`,
    summary: {
      completed: context.completedCount,
      failed: context.failedCount,
      total: 12,
    },
  }),
});

