import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'postExportComments',
  context: {
    owner: 'acme',
    repo: 'widgets',
    prs: [],
    prIndex: 0,
    currentPRNumber: 0,
    currentPRFiles: [],
    hasExportFiles: false,
    commentedPRs: [],
    skippedPRs: [],
  },
  initial: 'listingPRs',
  states: {
    listingPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title'],
      }), { id: 'listPRs' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listPRs'),
          target: 'checkingNextPR',
          actions: assign({
            prs: ({ event }) => event.result || [],
            prIndex: 0,
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            skippedPRs: () => ['Error listing PRs'],
          }),
        },
      },
    },
    checkingNextPR: {
      always: [
        {
          guard: ({ context }) => context.prIndex >= context.prs.length,
          target: 'done',
        },
        {
          target: 'gettingPRFiles',
          actions: assign({
            currentPRNumber: ({ context }) => context.prs[context.prIndex].number,
          }),
        },
      ],
    },
    gettingPRFiles: {
      entry: toolCall('github.pull_request_read', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        pullNumber: context.currentPRNumber,
        method: 'get_files',
        perPage: 100,
      }), { id: 'getFiles' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('getFiles'),
          target: 'checkingForExportFiles',
          actions: assign({
            currentPRFiles: ({ event }) => event.result || [],
          }),
        },
        TOOL_ERROR: {
          target: 'incrementPRIndex',
          actions: assign({
            skippedPRs: ({ context }) => [
              ...context.skippedPRs,
              `PR #${context.currentPRNumber}: Error getting files`,
            ],
          }),
        },
      },
    },
    checkingForExportFiles: {
      always: {
        target: 'decidingWhetherToComment',
        actions: assign({
          hasExportFiles: ({ context }) => {
            if (!Array.isArray(context.currentPRFiles)) {
              return false;
            }
            return context.currentPRFiles.some((file) => 
              typeof file === 'object' && file !== null && 'filename' in file &&
              typeof file.filename === 'string' &&
              file.filename.startsWith('src/export/')
            );
          },
        }),
      },
    },
    decidingWhetterToComment: {
      always: [
        {
          guard: ({ context }) => context.hasExportFiles,
          target: 'postingComment',
        },
        {
          target: 'incrementPRIndex',
        },
      ],
    },
    postingComment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        issue_number: context.currentPRNumber,
        body: 'Please add a CHANGELOG entry for the export changes.',
      }), { id: 'comment' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('comment'),
          target: 'incrementPRIndex',
          actions: assign({
            commentedPRs: ({ context }) => [
              ...context.commentedPRs,
              context.currentPRNumber,
            ],
          }),
        },
        TOOL_DENIED: {
          target: 'incrementPRIndex',
          actions: assign({
            skippedPRs: ({ context }) => [
              ...context.skippedPRs,
              `PR #${context.currentPRNumber}: Comment denied`,
            ],
          }),
        },
        TOOL_ERROR: {
          target: 'incrementPRIndex',
          actions: assign({
            skippedPRs: ({ context }) => [
              ...context.skippedPRs,
              `PR #${context.currentPRNumber}: Error posting comment`,
            ],
          }),
        },
      },
    },
    incrementPRIndex: {
      always: {
        target: 'checkingNextPR',
        actions: assign({
          prIndex: ({ context }) => context.prIndex + 1,
          hasExportFiles: false,
        }),
      },
    },
