import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'auditLogSync',
  context: {
    shippedOrders: [],
    existingAuditLogs: [],
    missingAuditLogs: [],
    insertedCount: 0,
    status: 'initial',
  },
  initial: 'fetchShippedOrders',
  states: {
    fetchShippedOrders: {
      entry: toolCall(
        'mongo.find',
        () => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'orders',
          filter: { status: 'shipped' },
          projection: { orderId: 1 },
        }),
        { id: 'findShipped' }
      ),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findShipped'),
          target: 'fetchExistingAuditLogs',
          actions: assign({
            shippedOrders: ({ event }) => event.result.documents,
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ status: 'Failed to fetch shipped orders' }),
        },
      },
    },
    fetchExistingAuditLogs: {
      entry: toolCall(
        'mongo.find',
        () => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'audit_log',
          filter: { action: 'shipped' },
          projection: { orderId: 1 },
        }),
        { id: 'findAuditLogs' }
      ),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findAuditLogs'),
          target: 'identifyMissing',
          actions: assign({
            existingAuditLogs: ({ event }) => event.result.documents,
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ status: 'Failed to fetch existing audit logs' }),
        },
      },
    },
    identifyMissing: {
      always: {
        target: 'insertMissing',
        actions: assign({
          missingAuditLogs: ({ context }) => {
            const existingOrderIds = new Set(
              context.existingAuditLogs.map((log) => log.orderId)
            );
            return context.shippedOrders
              .filter((order) => !existingOrderIds.has(order.orderId))
              .map((order) => ({
                orderId: order.orderId,
                action: 'shipped',
              }));
          },
        }),
      },
    },
    insertMissing: {
      always: [
        {
          guard: ({ context }) => context.missingAuditLogs.length === 0,
          target: 'done',
          actions: assign({ status: 'No missing audit logs' }),
        },
        {
          target: 'performInsert',
        },
      ],
    },
    performInsert: {
      entry: toolCall(
        'mongo.insert-many',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'audit_log',
          documents: context.missingAuditLogs,
        }),
        { id: 'insertAuditLogs' }
      ),
      on: {
        TOOL_RESULT: {
          guard: whenCall('insertAuditLogs'),
          target: 'done',
          actions: assign({
            insertedCount: ({ event }) => event.result.insertedCount,
            status: 'success',
          }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({ status: 'Insert was denied by user' }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ status: 'Failed to insert audit logs' }),
        },
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    status: context.status,
    shippedOrdersCount: context.shippedOrders.length,
    existingAuditLogsCount: context.existingAuditLogs.length,
    missingAuditLogsCount: context.missingAuditLogs.length,
    insertedCount: context.insertedCount,
  }),
});

import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'pr139-checks',
  context: {
    // Files that exist - need to create issues
    existingFiles: [
      'src/api/routes.ts',
      'src/db/pool.ts',
      'src/export/xml.ts',
      'src/cli/args.ts',
      'src/ui/chart.tsx',
      'docs/api.md'
    ],
    // Files that don't exist - need to comment on PR
    missingFiles: [
      'src/export/pdf.ts',
      'src/perf/bench.ts',
      'src/cache/lru.ts',
      'scripts/license.sh'
    ],
    issuesCreated: 0,
    commentsAdded: 0,
    currentFileIndex: 0,
    currentMissingIndex: 0,
    state: 'creating_issues'
  },
  initial: 'creating_issues',
  states: {
    creating_issues: {
      always: [
        {
          guard: ({ context }) => context.currentFileIndex < context.existingFiles.length,
          target: 'create_issue'
        },
        {
          target: 'adding_comments'
        }
      ]
    },
    create_issue: {
      entry: toolCall('github.issue_write', ({ context }) => {
        const file = context.existingFiles[context.currentFileIndex];
        return {
          method: 'create',
          owner: 'acme',
          repo: 'widgets',
          title: `Fix ${file}`
        };
      }, { id: 'create_issue_call' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('create_issue_call'),
          target: 'creating_issues',
          actions: assign({
            issuesCreated: ({ context }) => context.issuesCreated + 1,
            currentFileIndex: ({ context }) => context.currentFileIndex + 1
          })
        },
        TOOL_ERROR: {
          guard: whenCall('create_issue_call'),
          target: 'creating_issues',
          actions: assign({
            currentFileIndex: ({ context }) => context.currentFileIndex + 1
          })
        },
        TOOL_DENIED: {
          guard: whenCall('create_issue_call'),
          target: 'creating_issues',
          actions: assign({
            currentFileIndex: ({ context }) => context.currentFileIndex + 1
          })
        }
      }
    },
    adding_comments: {
      always: [
        {
          guard: ({ context }) => context.currentMissingIndex < context.missingFiles.length,
          target: 'add_comment'
        },
        {
          target: 'done'
        }
      ]
    },
    add_comment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => {
        const file = context.missingFiles[context.currentMissingIndex];
        return {
          owner: 'acme',
          repo: 'widgets',
          issue_number: 139,
          body: `File does not exist in project: ${file}`
        };
      }, { id: 'add_comment_call' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('add_comment_call'),
          target: 'adding_comments',
          actions: assign({
            commentsAdded: ({ context }) => context.commentsAdded + 1,
            currentMissingIndex: ({ context }) => context.currentMissingIndex + 1
          })
        },
        TOOL_ERROR: {
          guard: whenCall('add_comment_call'),
          target: 'adding_comments',
          actions: assign({
            currentMissingIndex: ({ context }) => context.currentMissingIndex + 1
          })
        },
        TOOL_DENIED: {
          guard: whenCall('add_comment_call'),
          target: 'adding_comments',
          actions: assign({
            currentMissingIndex: ({ context }) => context.currentMissingIndex + 1
          })
        }
      }
    },
    done: {
      type: 'final'
    }
  },
  output: ({ context }) => ({
    issuesCreated: context.issuesCreated,
    commentsAdded: context.commentsAdded,
    message: `Created ${context.issuesCreated} issues for existing files and added ${context.commentsAdded} comments for missing files.`
  })
});

import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'final_comments',
  context: {
    missingFiles: [
      'src/cache/lru.ts',
      'scripts/license.sh'
    ],
    currentIndex: 0,
    commentsAdded: 0
  },
  initial: 'processing',
  states: {
    processing: {
      always: [
        {
          guard: ({ context }) => context.currentIndex < context.missingFiles.length,
          target: 'add_comment'
        },
        {
          target: 'done'
        }
      ]
    },
    add_comment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => {
        const file = context.missingFiles[context.currentIndex];
        return {
          owner: 'acme',
          repo: 'widgets',
          issue_number: 139,
          body: `File does not exist in project: ${file}`
        };
      }, { id: 'add_comment_call' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('add_comment_call'),
          target: 'processing',
          actions: assign({
            commentsAdded: ({ context }) => context.commentsAdded + 1,
            currentIndex: ({ context }) => context.currentIndex + 1
          })
        },
        TOOL_ERROR: {
          guard: whenCall('add_comment_call'),
          target: 'processing',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1
          })
        },
        TOOL_DENIED: {
          guard: whenCall('add_comment_call'),
          target: 'processing',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1
          })
        }
      }
    },
    done: {
      type: 'final'
    }
  },
  output: ({ context }) => ({
    commentsAdded: context.commentsAdded,
    message: `Added ${context.commentsAdded} comments for remaining missing files.`
  })
});

