      'marco.rossi@example.com',
      'uma.patel@example.com',
      'liam.byrne@example.com',
      'bianca.neri@example.com',
      'emil.berg@example.com',
      'sofia.lund@example.com',
      'priya.nair@example.com',
      'oliver.grant@example.com',
    ],
    currentIndex: 0,
    missingVips: [] as string[],
    processedCount: 0,
  },
  initial: 'processEmails',
  states: {
    processEmails: {
      always: [
        {
          guard: ({ context }) => context.currentIndex < context.vipEmails.length,
          target: 'checkCustomer',
        },
        {
          target: 'writeMissingVips',
        },
      ],
    },
    checkCustomer: {
      entry: toolCall(
        'mongo.find',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.vipEmails[context.currentIndex] },
          limit: 1,
        }),
        { id: 'checkCustomer' }
      ),
      on: {
        TOOL_RESULT: [
          {
            guard: ({ event }) => event.result.documents.length > 0,
            target: 'updateCustomerTier',
          },
          {
            target: 'addToMissing',
          },
        ],
        TOOL_ERROR: {
          target: 'addToMissing',
        },
      },
    },
    updateCustomerTier: {
      entry: toolCall(
        'mongo.update-many',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.vipEmails[context.currentIndex] },
          update: { $set: { tier: 'gold' } },
        }),
        { id: 'updateCustomer' }
      ),
