        ],
      }),
      always: 'nextEmail',
    },
    nextEmail: {
      entry: assign({
        currentIndex: ({ context }) => context.currentIndex + 1,
        processedCount: ({ context }) => context.processedCount + 1,
      }),
      always: 'processEmails',
    },
    writeMissingVips: {
      always: [
        {
          guard: ({ context }) => context.missingVips.length > 0,
          target: 'writeFile',
        },
        {
          target: 'done',
        },
      ],
    },
    writeFile: {
      entry: toolCall(
        'fs.write_file',
        ({ context }) => ({
          path: 'notes/missing-vips.txt',
          content: context.missingVips.join('\n'),
        }),
        { id: 'writeFile' }
      ),
      on: {
        TOOL_RESULT: {
          guard: whenCall('writeFile'),
          target: 'done',
        },
        TOOL_DENIED: {
          target: 'done',
        },
        TOOL_ERROR: {
          target: 'done',
        },
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    processedCount: context.processedCount,
    missingVipCount: context.missingVips.length,
    missingVips: context.missingVips,
  }),
});

