import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'goldTierCustomerOrders',
  context: {
    connectionId: 'preconfigured',
    database: 'shop',
    collections: [],
    customers: [],
    results: [],
    currentStep: 'listing_collections',
  },
  initial: 'listCollections',
  states: {
    listCollections: {
      entry: toolCall('mongo.list-collections', ({ context }) => ({
        connectionId: context.connectionId,
        database: context.database,
      })),
      on: {
        TOOL_RESULT: {
          target: 'queryGoldCustomers',
          actions: assign({
            collections: ({ event }) => event.result.collections.map(c => c.name),
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            results: () => ['Error listing collections'],
          }),
        },
      },
    },
    queryGoldCustomers: {
      entry: toolCall('mongo.aggregate', ({ context }) => ({
        connectionId: context.connectionId,
        database: context.database,
        collection: 'customers',
        pipeline: [
          {
            $match: {
              tier: 'gold',
            },
          },
          {
            $lookup: {
              from: 'orders',
              localField: '_id',
              foreignField: 'customer_id',
              as: 'orders',
            },
          },
          {
            $addFields: {
              validOrders: {
                $filter: {
                  input: '$orders',
                  as: 'order',
                  cond: {
                    $ne: ['$$order.status', 'cancelled'],
                  },
                },
              },
            },
          },
          {
            $addFields: {
              totalValue: {
                $sum: '$validOrders.total',
              },
            },
          },
          {
            $project: {
              _id: 1,
              email: 1,
              totalValue: 1,
            },
          },
          {
            $sort: {
              email: 1,
            },
          },
        ],
      })),
      on: {
        TOOL_RESULT: {
          target: 'formatResults',
          actions: assign({
            customers: ({ event }) => event.result.documents,
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            results: () => ['Error querying customers'],
          }),
        },
      },
    },
    formatResults: {
      entry: assign({
        results: ({ context }) => {
          return context.customers.map(customer => {
            const total = (customer.totalValue || 0).toFixed(2);
            return `${customer.email}: $${total}`;
          });
        },
      }),
      type: 'final',
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    results: context.results,
  }),
});

