                .map(line => line.trim())
                .filter(line => line.startsWith('[FILE]'))
                .map(line => {
                  const match = line.match(/\[FILE\]\s+(.+?)(?:\s+\(|$)/);
                  return match ? match[1].trim() : '';
                })
                .filter(name => name.length > 0)
                .map(name => `logs/services/${name}`);
            },
          }),
        },
        TOOL_ERROR: 'failed',
      },
    },
    processingFiles: {
      on: {
        '': [
          {
            guard: ({ context }) => context.currentFileIndex >= context.files.length,
            target: 'done',
          },
          {
            target: 'readingFile',
          },
        ],
      },
    },
    readingFile: {
      entry: toolCall('fs.read_file', ({ context }) => ({
        path: context.files[context.currentFileIndex],
      })),
      on: {
        TOOL_RESULT: {
          target: 'countingErrors',
          actions: assign({
            results: ({ event, context }) => {
              const content = event.result as string;
              const lines = content.split('\n');
              const errorCount = lines.filter(line => line.includes('ERROR')).length;
              const fileName = context.files[context.currentFileIndex].split('/').pop() || 'unknown';
              return {
                ...context.results,
                [fileName]: errorCount,
              };
            },
          }),
        },
        TOOL_ERROR: {
          target: 'countingErrors',
          actions: assign({
            results: ({ context }) => {
              const fileName = context.files[context.currentFileIndex].split('/').pop() || 'unknown';
              return {
                ...context.results,
                [fileName]: 0,
              };
            },
          }),
        },
      },
    },
    countingErrors: {
      entry: assign({
        currentFileIndex: ({ context }) => context.currentFileIndex + 1,
      }),
      always: 'processingFiles',
    },
    done: { type: 'final' },
    failed: { type: 'final' },
  },
  output: ({ context }) => {
    const lines = Object.entries(context.results)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([name, count]) => `${name}: ${count}`);
    return lines.join('\n');
  },
});

